window.__ModuleLoader__.load({
  id: 'dsh-startup-animation',
  factory: (require) => {
    const React = require('react')

    const PKG = 'dsh-startup-animation'
    // 图层内联为无损 WebP 的 data URL：桌面端的 /plugins/<包>/assets/ 路由在宿主里取不到文件，
    // 内联后不依赖任何 HTTP 路由和转发。无损编码，与原始 PNG 合成结果逐像素一致
    // （只有 alpha=0 的不可见像素 RGB 被丢弃）。体积约 2MB，约为 PNG 的 1/4。
    const ASSET_DATA = {
      'character': 'data:image/webp;base64,',
      'bar-top': 'data:image/webp;base64,',
      'bar-mid': 'data:image/webp;base64,',
      'bar-bottom': 'data:image/webp;base64,',
      'whale-intro': 'data:image/webp;base64,',
      'wordmark': 'data:image/webp;base64,',
      'final': 'data:image/webp;base64,',
    }
    const STYLE_ID = 'dshs-startup-style'

    // ---------------------------------------------------------------- 设计坐标
    const STAGE = { w: 2048, h: 833 }
    const WHALE_CENTER = { x: 577.5, y: 542 }

    // 启动页（白底 HARNESS）交给壳，覆盖层只负责把它接到黑底再播动画。
    // 3 秒版：lead-in 0.30s + 动画 2.70s，节奏按“点亮→亮相→展开→落版”重新排过。
    const LEAD_IN = 0.3
    const ANIM = 2.7
    const TOTAL = LEAD_IN + ANIM

    // ---------------------------------------------------------------- 缓动/工具
    const easeOutCubic = (x) => 1 - Math.pow(1 - x, 3)
    const easeInOutCubic = (x) => (x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2)
    const linear = (x) => x
    const clamp01 = (x) => (x < 0 ? 0 : x > 1 ? 1 : x)
    const lerp = (a, b, p) => a + (b - a) * p

    /** 段内进度：开始前 0，结束后 1。 */
    const seg = (t, s) => {
      if (s.duration <= 0) return t >= s.start ? 1 : 0
      return (s.ease || linear)(clamp01((t - s.start) / s.duration))
    }

    // ---------------------------------------------------------------- 时间轴
    const T = {
      ambient:     { start: 0.0,  duration: 0.4,  ease: easeOutCubic },
      whale:       { start: 0.04, duration: 0.3,  ease: easeOutCubic },
      character:   { start: 0.4,  duration: 0.12, ease: easeOutCubic },
      scan:        { start: 0.36, duration: 0.5,  ease: easeInOutCubic },
      rings:       { start: 0.8,  duration: 0.52, ease: easeOutCubic },
      bars: {
        top:    { start: 1.18, duration: 0.28, ease: easeOutCubic, fromX: 1215 },
        mid:    { start: 1.25, duration: 0.27, ease: easeOutCubic, fromX: 811 },
        bottom: { start: 1.32, duration: 0.26, ease: easeOutCubic, fromX: 781 },
      },
      wordmark:    { start: 1.6,  duration: 0.24, ease: easeOutCubic },
      subtitle:    { start: 1.84, duration: 0.22, ease: easeOutCubic },
      takeover:    { start: 1.86, duration: 0.16, ease: linear },
      exit:        { start: 2.28, duration: 0.42, ease: easeInOutCubic },
    }

    const U = {
      whale: { scaleFrom: 0.96, brightnessFrom: 1.04, glowFrom: 5, glowTo: 2, pulse: 0.06 },
      character: { scaleFrom: 1.014, yFrom: 10 },
      scan: { xFrom: -90, xTo: 1770, width: 54 },
      rings: { count: 3, cx: 860, cy: 465, rx: 520, ry: 288, stagger: 0.14, duration: 0.9,
               scaleFrom: 0.5, scaleTo: 1.12, opacity: 0.5 },
      bars: { softEdge: 18 },
      wordmark: { blurFrom: 18, scaleFrom: 1.05, brightnessFrom: 1.7 },
      subtitle: { spacingFrom: 0.58, spacingTo: 0.3, yFrom: 12 },
    }

    const CSS = [
      '.dshs-root{position:fixed;inset:0;overflow:hidden;pointer-events:auto;z-index:0;',
      '  background:var(--dsw-alias-bg-base,#fff);will-change:opacity;',
      '  font-family:"Segoe UI",system-ui,-apple-system,"Microsoft YaHei",sans-serif}',
      '.dshs-stage{position:absolute;left:50%;top:50%;width:2048px;height:833px;',
      '  transform:translate(-50%,-50%) scale(.5);transform-origin:50% 50%}',
      '.dshs-veil{position:absolute;inset:0;background:#000;opacity:0;pointer-events:none}',
      '.dshs-media{position:absolute;inset:0;width:100%;height:100%;object-fit:contain;background:#000}',
      '.dshs-stars,.dshs-stack,.dshs-scan{position:absolute;inset:0}',
      '.dshs-star{position:absolute;border-radius:50%;background:#cdeaff;',
      '  box-shadow:0 0 6px rgba(140,215,255,.75);opacity:0}',
      '.dshs-layer{position:absolute;inset:0;width:100%;height:100%;display:block;',
      '  user-select:none;-webkit-user-drag:none}',
      '.dshs-rings{position:absolute;inset:0;pointer-events:none}',
      '.dshs-ring{position:absolute;border:2px solid rgba(150,226,255,.85);border-radius:50%;',
      '  opacity:0;transform-origin:50% 50%;box-shadow:0 0 22px rgba(90,200,255,.55),',
      '  0 0 60px rgba(50,150,255,.28),inset 0 0 40px rgba(80,190,255,.16)}',
      '.dshs-scan{opacity:0;pointer-events:none}',
      '.dshs-scan-bar{position:absolute;top:0;bottom:0;left:0;',
      '  background:linear-gradient(90deg,transparent 0%,rgba(96,196,255,.05) 22%,rgba(198,240,255,.5) 44%,',
      '  rgba(255,255,255,.95) 50%,rgba(170,232,255,.55) 56%,rgba(90,180,255,.06) 78%,transparent 100%);',
      '  filter:blur(.4px);',
      '  -webkit-mask-image:linear-gradient(180deg,transparent 0%,#000 14%,#000 80%,transparent 100%);',
      '  mask-image:linear-gradient(180deg,transparent 0%,#000 14%,#000 80%,transparent 100%)}',
      '.dshs-final{opacity:0}',
      '.dshs-subtitle{position:absolute;left:754px;top:768px;opacity:0;',
      '  font-weight:300;font-size:33px;line-height:1;letter-spacing:.3em;color:#d3e9ff;',
      '  text-shadow:0 0 20px rgba(80,190,255,.55);white-space:nowrap}',
      '.dshs-ambient{position:absolute;inset:0;opacity:0;pointer-events:none;mix-blend-mode:screen;',
      '  background:radial-gradient(42% 52% at 30% 50%,rgba(18,78,156,.5),transparent 70%),',
      '  radial-gradient(34% 44% at 63% 47%,rgba(24,136,196,.3),transparent 72%)}',
      '.dshs-hint{position:absolute;right:26px;bottom:26px;font-size:13px;letter-spacing:.08em;',
      '  color:rgba(206,222,238,.6);opacity:0;pointer-events:none}',
    ].join('\n')

    function installStyle() {
      if (document.getElementById(STYLE_ID) !== null) return
      const style = document.createElement('style')
      style.id = STYLE_ID
      style.textContent = CSS
      document.head.append(style)
    }

    function el(tag, className, parent) {
      const node = document.createElement(tag)
      if (className) node.className = className
      if (parent) parent.append(node)
      return node
    }

    function imgLayer(name, parent) {
      const img = el('img', 'dshs-layer dshs-' + name, parent)
      img.src = ASSET_DATA[name]
      img.alt = ''
      img.draggable = false
      img.decoding = 'async'
      return img
    }

    /** 固定的伪随机星点，刷新后位置不变。 */
    function starSpecs(count) {
      let seed = 0x2f6e2b1
      const rnd = () => {
        seed = (seed * 1664525 + 1013904223) >>> 0
        return seed / 0xffffffff
      }
      const out = []
      for (let i = 0; i < count; i += 1) {
        out.push({ x: rnd() * STAGE.w, y: rnd() * STAGE.h, size: 1 + rnd() * 1.8, phase: rnd() * Math.PI * 2 })
      }
      return out
    }

    function build(root) {
      const veil = el('div', 'dshs-veil', root)
      const stage = el('div', 'dshs-stage', root)

      const starField = el('div', 'dshs-stars', stage)
      const stars = starSpecs(26).map((s) => {
        const dot = el('i', 'dshs-star', starField)
        dot.style.left = s.x + 'px'
        dot.style.top = s.y + 'px'
        dot.style.width = s.size + 'px'
        dot.style.height = s.size + 'px'
        dot.dataset.phase = String(s.phase)
        return dot
      })

      const stack = el('div', 'dshs-stack', stage)
      const ringField = el('div', 'dshs-rings', stack)
      const rings = []
      for (let i = 0; i < U.rings.count; i += 1) {
        const ring = el('div', 'dshs-ring', ringField)
        ring.style.left = U.rings.cx - U.rings.rx + 'px'
        ring.style.top = U.rings.cy - U.rings.ry + 'px'
        ring.style.width = U.rings.rx * 2 + 'px'
        ring.style.height = U.rings.ry * 2 + 'px'
        rings.push(ring)
      }

      const bars = {
        top: imgLayer('bar-top', stack),
        mid: imgLayer('bar-mid', stack),
        bottom: imgLayer('bar-bottom', stack),
      }
      const character = imgLayer('character', stack)
      const whale = imgLayer('whale-intro', stack)
      const wordmark = imgLayer('wordmark', stack)

      const scan = el('div', 'dshs-scan', stage)
      const scanBar = el('div', 'dshs-scan-bar', scan)
      scanBar.style.width = U.scan.width + 'px'

      const final = imgLayer('final', stage)
      const subtitle = el('div', 'dshs-subtitle', stage)
      subtitle.textContent = 'HARNESS'

      const ambient = el('div', 'dshs-ambient', root)
      const hint = el('div', 'dshs-hint', root)
      hint.textContent = '点击任意处跳过'

      const images = [bars.top, bars.mid, bars.bottom, character, whale, wordmark, final]
      return { root, veil, stage, stack, stars, rings, bars, character, whale, wordmark, scan, scanBar, final, subtitle, ambient, hint, images }
    }

    function layout(refs) {
      const scale = Math.min(window.innerWidth / STAGE.w, window.innerHeight / STAGE.h)
      refs.stage.style.transform = 'translate(-50%,-50%) scale(' + scale + ')'
    }

    /** 纯渲染：给定动画时间 t（秒）写出所有图层状态。 */
    function render(t, refs) {
      const ambient = seg(t, T.ambient)
      refs.ambient.style.opacity = String(ambient * 0.6)
      for (const star of refs.stars) {
        const phase = Number(star.dataset.phase || 0)
        const twinkle = 0.55 + 0.45 * Math.sin(t * 2.1 + phase)
        const fade = clamp01((t - 0.05) / 0.5) * (1 - clamp01((t - 1.85) / 0.5))
        star.style.opacity = String(0.16 + 0.32 * twinkle * fade)
      }

      const whaleIn = seg(t, T.whale)
      const charIn = seg(t, T.character)
      const whaleOut = 1 - charIn
      const pulse = 1 + U.whale.pulse * Math.sin(t * 3.4) * whaleIn * whaleOut
      refs.whale.style.opacity = String(whaleIn * whaleOut)
      refs.whale.style.transformOrigin = WHALE_CENTER.x + 'px ' + WHALE_CENTER.y + 'px'
      refs.whale.style.transform = 'scale(' + lerp(U.whale.scaleFrom, 1, whaleIn) + ')'
      const glow = lerp(U.whale.glowFrom, U.whale.glowTo, whaleIn) * pulse
      const bright = lerp(U.whale.brightnessFrom, 1, whaleIn)
      refs.whale.style.filter =
        'brightness(' + bright.toFixed(3) + ') drop-shadow(0 0 ' + glow.toFixed(1) + 'px rgba(64,214,255,.75))'

      refs.character.style.opacity = String(charIn)
      refs.character.style.transform =
        'translateY(' + lerp(U.character.yFrom, 0, charIn).toFixed(2) + 'px) scale(' +
        lerp(U.character.scaleFrom, 1, charIn).toFixed(4) + ')'
      refs.character.style.filter = 'brightness(' + lerp(1.16, 1, charIn).toFixed(3) + ')'

      const scanP = seg(t, T.scan)
      const scanOn = t >= T.scan.start && t <= T.scan.start + T.scan.duration + 0.05
      const scanFade = Math.min(clamp01((scanP - 0.02) / 0.12), clamp01((1.02 - scanP) / 0.18))
      refs.scan.style.opacity = scanOn ? String(scanFade) : '0'
      refs.scan.style.transform = 'translateX(' + lerp(U.scan.xFrom, U.scan.xTo, scanP).toFixed(1) + 'px)'

      for (let i = 0; i < refs.rings.length; i += 1) {
        const ring = refs.rings[i]
        const local = (t - T.rings.start - i * U.rings.stagger) / U.rings.duration
        if (local <= 0 || local >= 1) {
          ring.style.opacity = '0'
          continue
        }
        const p = easeOutCubic(clamp01(local))
        ring.style.opacity = String(U.rings.opacity * Math.pow(1 - p, 1.5))
        ring.style.transform = 'scale(' + lerp(U.rings.scaleFrom, U.rings.scaleTo, p).toFixed(4) + ')'
      }

      for (const key of ['top', 'mid', 'bottom']) {
        const s = T.bars[key]
        const p = seg(t, s)
        const node = refs.bars[key]
        if (p <= 0) {
          node.style.opacity = '0'
          continue
        }
        node.style.opacity = '1'
        const edge = lerp(s.fromX, STAGE.w, p)
        const mask =
          'linear-gradient(90deg,#000 ' + (edge - U.bars.softEdge).toFixed(1) + 'px,transparent ' + (edge + 2).toFixed(1) + 'px)'
        node.style.maskImage = mask
        node.style.webkitMaskImage = mask
      }

      const wm = seg(t, T.wordmark)
      refs.wordmark.style.opacity = String(clamp01(wm * 1.6))
      refs.wordmark.style.filter =
        'blur(' + lerp(U.wordmark.blurFrom, 0, wm).toFixed(2) + 'px) brightness(' +
        lerp(U.wordmark.brightnessFrom, 1, wm).toFixed(3) + ')'
      refs.wordmark.style.transform = 'scale(' + lerp(U.wordmark.scaleFrom, 1, wm).toFixed(4) + ')'

      const sub = seg(t, T.subtitle)
      refs.subtitle.style.opacity = String(sub)
      refs.subtitle.style.transform = 'translateY(' + lerp(U.subtitle.yFrom, 0, sub).toFixed(2) + 'px)'
      refs.subtitle.style.letterSpacing = lerp(U.subtitle.spacingFrom, U.subtitle.spacingTo, sub).toFixed(3) + 'em'

      const takeover = seg(t, T.takeover)
      refs.final.style.opacity = String(takeover)
      refs.stack.style.opacity = String(1 - takeover)

      const hintIn = clamp01((t - 0.45) / 0.3) * (1 - clamp01((t - 1.7) / 0.5))
      refs.hint.style.opacity = String(hintIn * 0.62)

      const exit = seg(t, T.exit)
      refs.root.style.opacity = String(1 - exit)
    }

    // ---------------------------------------------------------------- 播放器
    /**
     * 挂载一次启动动画。
     * @param host 承载节点（覆盖层的根 div）
     * @param options onDone 动画结束回调；freezeAt 用于本地自检定格
     * @returns { dispose, seek }
     */
    function mount(host, options) {
      const opts = options || {}
      const speed = typeof opts.speed === 'number' && opts.speed > 0 ? opts.speed : 1
      installStyle()
      const root = el('div', 'dshs-root', host)
      const refs = build(root)
      // 接住启动页的底色：主题变量优先，其次按暗色标记兜底
      const themeBase = getComputedStyle(document.body).getPropertyValue('--dsw-alias-bg-base').trim()
      root.style.background = themeBase !== ''
        ? themeBase
        : (document.body.hasAttribute('data-ds-dark-theme') ? '#0f1115' : '#ffffff')
      const cleanups = []
      let raf = 0
      let lastTs = 0
      let elapsed = 0
      let skipped = false
      let finished = false

      layout(refs)
      const onResize = () => layout(refs)
      window.addEventListener('resize', onResize)
      cleanups.push(() => window.removeEventListener('resize', onResize))

      const onSkip = () => {
        if (skipped || finished) return
        skipped = true
        elapsed = Math.max(elapsed, LEAD_IN + T.exit.start + 0.001)
        stepFrame(0)
      }
      const onClick = () => onSkip()
      const onKey = (event) => {
        if (event.key === 'Escape') onSkip()
      }
      root.addEventListener('click', onClick)
      window.addEventListener('keydown', onKey)
      cleanups.push(() => root.removeEventListener('click', onClick))
      cleanups.push(() => window.removeEventListener('keydown', onKey))

      const finish = () => {
        if (finished) return
        finished = true
        cancelAnimationFrame(raf)
        // 结束后必须把节点拿掉：它是 fixed 满屏、pointer-events:auto，留着会吞掉应用的所有点击
        root.style.pointerEvents = 'none'
        root.remove()
        for (const fn of cleanups) fn()
        if (typeof opts.onDone === 'function') opts.onDone()
      }

      /** 前 LEAD_IN 秒：主题底色被黑色幕布逐渐盖住，之后一直是纯黑。 */
      const setVeil = (k) => { refs.veil.style.opacity = k.toFixed(4) }
      const applyLeadIn = (clock) => {
        const p = clamp01((clock - 0.12) / Math.max(LEAD_IN - 0.12, 0.01))
        setVeil(easeInOutCubic(p))
      }

      function stepFrame(dt) {
        try {
          advance(dt)
        } catch (error) {
          console.error('[startup-animation] render failed', error)
          finish()
        }
      }

      function advance(dt) {
        elapsed += dt * speed
        if (elapsed < LEAD_IN) {
          applyLeadIn(elapsed)
          render(0, refs)
        } else if (!ready) {
          setVeil(1)
          elapsed = LEAD_IN
          render(0, refs)
        } else {
          setVeil(1)
          const t = elapsed - LEAD_IN
          render(Math.min(t, ANIM), refs)
          if (t >= ANIM) {
            finish()
            return
          }
        }
        if (!finished) raf = requestAnimationFrame(onFrame)
      }

      function onFrame(ts) {
        if (lastTs === 0) {
          lastTs = ts
          stepFrame(0.016)
          return
        }
        const dt = Math.min((ts - lastTs) / 1000, 0.1)
        lastTs = ts
        stepFrame(dt)
      }

      // 素材解码和 lead-in 并行：解码没完成就停在黑幕上等，不要让用户看到半张图
      let ready = false
      const markReady = () => { ready = true }
      const decodeAll = Promise.all(
        refs.images.map((img) => {
          if (typeof img.decode === 'function') return img.decode().catch(() => undefined)
          return new Promise((resolve) => {
            img.addEventListener('load', resolve, { once: true })
            img.addEventListener('error', resolve, { once: true })
          })
        }),
      )
      decodeAll.then(markReady)
      const guard = setTimeout(markReady, 1800)
      cleanups.push(() => clearTimeout(guard))

      render(0, refs)
      if (opts.freezeAt !== undefined) {
        ready = true
        elapsed = LEAD_IN + opts.freezeAt
        setVeil(1)
        render(opts.freezeAt, refs)
      } else {
        raf = requestAnimationFrame(onFrame)
      }

      return {
        dispose() {
          finished = true
          cancelAnimationFrame(raf)
          for (const fn of cleanups) fn()
          root.remove()
        },
        seek(t) {
          elapsed = LEAD_IN + t
          setVeil(1)
          render(t, refs)
        },
      }
    }

    // ---------------------------------------------------------------- 自定义开场
    /** 读取 localStorage 里的覆盖配置；没有或损坏时回落到内置动画。 */
    function readIntroConfig() {
      try {
        const raw = localStorage.getItem('dsh.startup.intro')
        if (raw === null || raw === '') return { kind: 'builtin' }
        const parsed = JSON.parse(raw)
        if (parsed === null || typeof parsed !== 'object') return { kind: 'builtin' }
        return parsed
      } catch (_error) {
        return { kind: 'builtin' }
      }
    }

    /** 内置动画是否被用户关掉。 */
    function introDisabled() {
      try {
        return localStorage.getItem('dsh.startup.disabled') === '1'
      } catch (_error) {
        return false
      }
    }

    /**
     * 用一段视频或一张图替换整段开场。
     * @param host 承载节点
     * @param intro { kind:'video'|'image', url, duration?, fadeOut?, hint?, loop? }
     */
    function mountMedia(host, intro) {
      installStyle()
      const root = el('div', 'dshs-root', host)
      root.style.background = '#000'
      const media = document.createElement(intro.kind === 'video' ? 'video' : 'img')
      media.className = 'dshs-media'
      media.src = String(intro.url === undefined ? '' : intro.url)
      if (intro.kind === 'video') {
        media.autoplay = true
        media.muted = true
        media.playsInline = true
        if (intro.loop === true) media.loop = true
      }
      root.append(media)
      const hint = el('div', 'dshs-hint', root)
      hint.textContent = typeof intro.hint === 'string' ? intro.hint : '点击任意处跳过'
      hint.style.opacity = '0.62'

      const fadeOut = typeof intro.fadeOut === 'number' && intro.fadeOut >= 0 ? intro.fadeOut : 0.4
      let timer = 0
      let closed = false
      const close = () => {
        if (closed) return
        closed = true
        clearTimeout(timer)
        root.style.transition = 'opacity ' + fadeOut + 's ease'
        root.style.opacity = '0'
        setTimeout(() => { root.remove() }, Math.max(fadeOut, 0) * 1000 + 60)
      }
      const onClick = () => close()
      const onKey = (event) => { if (event.key === 'Escape') close() }
      root.addEventListener('click', onClick)
      window.addEventListener('keydown', onKey)

      const limit = typeof intro.duration === 'number' && intro.duration > 0
        ? intro.duration
        : (intro.kind === 'video' ? 0 : 3)
      if (limit > 0) timer = setTimeout(close, limit * 1000)
      const fail = () => close()
      media.addEventListener('error', fail)
      if (intro.kind === 'video') media.addEventListener('ended', close)

      return {
        dispose() {
          clearTimeout(timer)
          root.removeEventListener('click', onClick)
          window.removeEventListener('keydown', onKey)
          root.remove()
        },
        seek() {},
      }
    }

    /**
     * 真实启动入口：按 localStorage 配置决定播放内置动画、自定义媒体，还是完全不播。
     * 组件和本地自检都走这一条路径，避免测的和跑的不是同一段代码。
     */
    function startIntro(host) {
      if (introDisabled()) return null
      const intro = readIntroConfig()
      if (intro.kind === 'video' || intro.kind === 'image') return mountMedia(host, intro)
      return mount(host, { speed: intro.speed })
    }

    // ---------------------------------------------------------------- React 接入
    let played = false

    function StartupOverlay() {
      const hostRef = React.useRef(null)
      React.useEffect(() => {
        const host = hostRef.current
        if (host === null || played) return undefined
        played = true
        let controller = null
        try {
          controller = startIntro(host)
        } catch (error) {
          console.error('[startup-animation] mount failed', error)
          host.replaceChildren()
          return undefined
        }
        return () => { if (controller !== null) controller.dispose() }
      }, [])
      return React.createElement('div', { ref: hostRef })
    }

    return {
      name: 'startup-animation',
      inject: ['slots'],
      apply(ctx) {
        ctx.slots.inject('shell.overlay', () =>
          ctx.slots.register(
            { name: 'shell.overlay', id: 'startup.animation', order: 1000, inject: () => ({}) },
            StartupOverlay,
          ),
        )
      },
      __debug: { mount, render, build, installStyle, start: startIntro, mountMedia },
    }
  },
})
